// Blink LD2, and an LED on D13, at 3.3 V
// Resistor in series with the breadboard LED: 220 Ω
const int LED_PIN = LED_BUILTIN;  // D13 = PA5, the green LD2 on the board

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);  // 3.3 V
  delay(500);
  digitalWrite(LED_PIN, LOW);   // 0 V
  delay(500);
}
